function tcd_esp_dentro( $x, $y, $anel ) {
	$in = false; $n = count( $anel );
	for ( $i = 0, $j = $n - 1; $i < $n; $j = $i++ ) {
		$xi = $anel[ $i ][0]; $yi = $anel[ $i ][1]; $xj = $anel[ $j ][0]; $yj = $anel[ $j ][1];
		if ( ( $yi > $y ) !== ( $yj > $y ) && $x < ( $xj - $xi ) * ( $y - $yi ) / ( ( $yj - $yi ) ?: 1e-12 ) + $xi ) { $in = ! $in; }
	}
	return $in;
}
// Distância aproximada (km) do ponto à fronteira terrestre com Espanha (vértices 215 a 430 e 0 a 2 do anel; o resto é
// costa), em projecção local equirrectangular.
function tcd_esp_dist_km( $x, $y, $anel ) {
	$k = cos( deg2rad( $y ) ); $min = INF; $n = count( $anel );
	for ( $i = 0; $i + 1 < $n; $i++ ) {
		if ( ! ( $i >= 215 || $i < 2 ) ) { continue; }
		$ax = ( $anel[ $i ][0] - $x ) * $k; $ay = $anel[ $i ][1] - $y; $bx = ( $anel[ $i + 1 ][0] - $x ) * $k; $by = $anel[ $i + 1 ][1] - $y;
		$dx = $bx - $ax; $dy = $by - $ay; $l2 = $dx * $dx + $dy * $dy;
		$t = $l2 > 0 ? max( 0, min( 1, -( $ax * $dx + $ay * $dy ) / $l2 ) ) : 0;
		$px = $ax + $t * $dx; $py = $ay + $t * $dy; $d = sqrt( $px * $px + $py * $py );
		if ( $d < $min ) { $min = $d; }
	}
	return $min * 111.32;
}
// 'PT', 'PT_FRONTEIRA', 'ES' (Península e Baleares), 'ES_ILHAS' (Canárias, Ceuta, Melilla) ou '' (outro).
function tcd_esp_pais( $lng, $lat ) {
	$lng = (float) $lng; $lat = (float) $lat;
	if ( $lng >= -32.5 && $lng <= -12.5 && $lat >= 29.5 && $lat <= 40.0 ) { return 'PT'; } // Açores e Madeira
	if ( $lng >= -18.3 && $lng <= -13.3 && $lat >= 27.5 && $lat <= 29.5 ) { return 'ES_ILHAS'; } // Canárias
	if ( $lng >= -5.45 && $lng <= -2.85 && $lat >= 35.2 && $lat <= 35.95 ) { return 'ES_ILHAS'; } // Ceuta e Melilla
	if ( $lng < -9.6 || $lng > 4.4 || $lat < 35.9 || $lat > 43.9 ) { return ''; }
	$anel = tcd_esp_pt_anel();
	if ( $lng < -6.1 && $lat < 42.2 && tcd_esp_dist_km( $lng, $lat, $anel ) < 3.0 ) { return 'PT_FRONTEIRA'; }
	if ( tcd_esp_dentro( $lng, $lat, $anel ) ) { return 'PT'; }
	if ( $lng >= 1.1 && $lng <= 4.4 && $lat >= 38.6 && $lat <= 40.2 ) { return 'ES'; } // Baleares
	if ( function_exists( 'tcd_esp_es_anel' ) && ! tcd_esp_dentro( $lng, $lat, tcd_esp_es_anel() ) ) { return ''; } // França, Andorra
	return 'ES';
}
